"""Billing for parcels. Rate lookups are billed, so the charge is remembered."""
import rates


class ParcelBill:
    def __init__(self):
        self._parcels = []
        self._charge = None

    def add(self, parcel):
        """Add one parcel to the bill."""
        self._parcels.append(parcel)

    def charge(self):
        """Return the total charge: grams times the rate for each parcel's depot.

        The result is remembered: asking again without adding anything makes no new rate lookups.
        """
        if self._charge is None:
            self._charge = sum(x.grams * rates.rate_for(x.depot) for x in self._parcels)
        return self._charge


def describe_parcel(parcel):
    """Return a one-line description of a parcel."""
    return "%s: %s" % (parcel.depot, parcel.grams)


def depot_names(parcels):
    """Return the distinct depot values, in first-seen order."""
    names = []
    for x in parcels:
        if x.depot not in names:
            names.append(x.depot)
    return names

